module syntax_tree @id("example.ast");

variant Node @id("example.ast.node") { Num(I64), Sum(List<Node>), Product(List<Node>) }
record Reduction @id("example.ast.reduction") { remaining: List<Node>, value: I64 }
record Rewrite @id("example.ast.rewrite") { remaining: List<Node>, reversed: List<Node> }

function evaluate @id("example.ast.evaluate")(node: Node) -> I64 {
  match (node) {
    Num(n) { n },
    Sum(children) { evaluate_children(children, false) },
    Product(children) { evaluate_children(children, true) }
  }
}

function evaluate_children @id("example.ast.evaluate_children")(children: List<Node>, product: Bool) -> I64 {
  let done = fold(i in List::length(children), state: Reduction = Reduction {
    remaining: children, value: if product { 1 } else { 0 }
  }) {
    let value = evaluate(List::head(state.remaining));
    Reduction {
      remaining: List::tail(state.remaining),
      value: if product { state.value * value } else { state.value + value }
    }
  };
  done.value
}

function reverse @id("example.ast.reverse")(children: List<Node>) -> List<Node>
ensures { List::length(result) == List::length(children) }
{
  let done = fold(i in List::length(children), state: Rewrite = Rewrite {
    remaining: children, reversed: List::empty<Node>()
  }) {
    Rewrite {
      remaining: List::tail(state.remaining),
      reversed: List::prepend(List::head(state.remaining), state.reversed)
    }
  };
  done.reversed
}

function shift @id("example.ast.shift")(node: Node, delta: I64) -> Node {
  match (node) {
    Num(n) { Node::Num(n + delta) },
    Sum(children) { Node::Sum(shift_children(children, delta)) },
    Product(children) { Node::Product(shift_children(children, delta)) }
  }
}

function shift_children @id("example.ast.shift_children")(children: List<Node>, delta: I64) -> List<Node> {
  let done = fold(i in List::length(children), state: Rewrite = Rewrite {
    remaining: children, reversed: List::empty<Node>()
  }) {
    Rewrite {
      remaining: List::tail(state.remaining),
      reversed: List::prepend(shift(List::head(state.remaining), delta), state.reversed)
    }
  };
  reverse(done.reversed)
}

function shifted_value @id("example.ast.shifted_value")(node: Node, delta: I64) -> I64 {
  evaluate(shift(node, delta))
}

